<script>
(function($){const api='discounts_api.php',modal=$('#uni_modal'),editId=<?php echo $discount_id;?>,editSource=<?php echo json_encode($discount_source);?>;let debts=[],request=null,selectedDebt=null,editData=null;const money=v=>'S/ '+Number(v||0).toFixed(2),esc=v=>$('<div>').text(v==null?'':v).html(),error=m=>$('#discount-message').html('<div class="alert alert-danger">'+esc(m)+'</div>');
function calculatedFinal(){if(!selectedDebt)return null;const entered=parseFloat($('#discount-value').val()),current=Number(selectedDebt.effective||0),type=$('#discount-calc').val();if(!Number.isFinite(entered))return null;if(type==='Monto descontado')return current-entered;if(type==='Porcentaje')return current-(current*entered/100);return entered}
function updatePreview(){const finalAmount=calculatedFinal();if(!selectedDebt||finalAmount===null){$('#discount-preview').addClass('d-none');return}const current=Number(selectedDebt.effective||0),paid=Number(selectedDebt.paid||0),discount=Math.max(0,current-finalAmount),balance=Math.max(0,finalAmount-paid);$('#preview-current').text(money(current));$('#preview-discount').text('- '+money(discount));$('#preview-final').text(money(finalAmount));$('#preview-paid').text(money(paid));$('#preview-balance').text(money(balance));$('#discount-preview').removeClass('d-none');}
function initSelects(){$('#discount-student').select2({width:'100%',dropdownParent:modal,placeholder:'Buscar estudiante',allowClear:true});$('#discount-debt').select2({width:'100%',dropdownParent:modal,placeholder:'Seleccione una deuda',allowClear:true})}initSelects();
$.getJSON(api+'?action=students').done(r=>{(r.data||[]).forEach(s=>$('#discount-student').append(new Option(s.id_no+' - '+s.name+' · '+s.nivel+' '+s.grado,s.id)));$('#discount-student').trigger('change.select2');if(editId)$.getJSON(api+'?action=detail&id='+editId+'&source='+editSource).done(d=>{editData=d.data;if(!$('#discount-student option[value="'+editData.student_id+'"]').length)$('#discount-student').append(new Option(editData.id_no+' - '+editData.student_name,editData.student_id));if(editData.payment_operation_id)$('#discount-message').html('<div class="alert alert-info"><i class="fas fa-receipt mr-1"></i> Este descuento ya fue utilizado en una boleta. Al guardar, la boleta anterior será anulada y se emitirá una nueva con correlativo propio.</div>');$('#discount-student').val(String(editData.student_id)).trigger('change')}).fail(x=>error((x.responseJSON||{}).message||'No se pudo cargar el descuento.'))}).fail(x=>error((x.responseJSON||{}).message||'No se pudieron cargar los estudiantes.'));
$('#discount-student').on('change',function(){const studentId=this.value;debts=[];selectedDebt=null;if(request)request.abort();$('#discount-summary,#discount-preview').addClass('d-none');$('#discount-value').val('').prop('disabled',true).attr('placeholder','Primero seleccione una deuda');$('#discount-debt').empty().append(new Option('','',true,true)).prop('disabled',true).trigger('change.select2');$('#debt-help').text(studentId?'Cargando deudas del estudiante...':'Seleccione primero un estudiante.');if(!studentId)return;request=$.getJSON(api+'?action=debts&student_id='+encodeURIComponent(studentId)).done(r=>{if($('#discount-student').val()!==String(studentId))return;debts=r.data||[];if(editData&&!debts.some(d=>String(d.debt_id)===String(editData.debt_id)))debts.push({debt_id:editData.debt_id,course:editData.course||'Concepto',year:editData.year||'Sin año',effective:Number(editData.previous_effective_amount),paid:Number(editData.paid||0),available:Math.max(0,Number(editData.previous_effective_amount)-Number(editData.paid||0))});$('#discount-debt').empty().append(new Option('','',true,true));debts.forEach(d=>$('#discount-debt').append(new Option(d.course+' · '+(d.year||'Sin año')+' · saldo '+money(d.available),d.debt_id)));$('#discount-debt').prop('disabled',!debts.length).trigger('change.select2');$('#debt-help').text(editData?'Deuda vinculada al descuento. No puede cambiarse durante la edición.':(debts.length?'Seleccione el concepto al que aplicará el beneficio.':'Este estudiante no tiene deudas activas con saldo pendiente.'));if(editData){let editingDebt=debts.find(d=>String(d.debt_id)===String(editData.debt_id));if(editingDebt){editingDebt.effective=Number(editData.previous_effective_amount);editingDebt.paid=Number(editData.paid||editingDebt.paid||0);editingDebt.available=Math.max(0,editingDebt.effective-editingDebt.paid)}$('#discount-debt').val(String(editData.debt_id)).trigger('change');$('[name="benefit_type"]').val(editData.benefit_type);$('#discount-calc').val(editData.calculation_type);$('#discount-value').val(editData.value);$('[name="valid_from"]').val(editData.valid_from||'');$('[name="valid_until"]').val(editData.valid_until||'');$('[name="reason"]').val(editData.reason||'');$('[name="notes"]').val(editData.notes||'');updatePreview();$('#discount-student,#discount-debt').prop('disabled',true).trigger('change.select2');if(!$('#discount-form input[name="debt_id"][type="hidden"]').length)$('#discount-form').append('<input type="hidden" name="debt_id" value="'+editData.debt_id+'">')}}).fail((x,status)=>{if(status!=='abort'){error((x.responseJSON||{}).message||'No se pudieron cargar las deudas.');$('#debt-help').text('No se pudieron cargar las deudas.')}})});
$('#discount-debt').on('change',function(){selectedDebt=debts.find(x=>String(x.debt_id)===String(this.value))||null;if(!selectedDebt){$('#discount-summary,#discount-preview').addClass('d-none');$('#discount-value').val('').prop('disabled',true);return}$('#sum-current').text(money(selectedDebt.effective));$('#sum-paid').text(money(selectedDebt.paid));$('#sum-available').text(money(selectedDebt.available));$('#discount-summary').removeClass('d-none');$('#discount-calc').val('Monto final');$('#discount-value').prop('disabled',false).attr({min:Number(selectedDebt.paid||0).toFixed(2),max:Number(selectedDebt.effective||0).toFixed(2),placeholder:'Ej.: '+Number(selectedDebt.effective||0).toFixed(2)}).val('').focus();$('#discount-value-label').text('¿Cuál será el monto final a pagar? (S/)');$('#discount-value-help').text('Puede ingresar desde '+money(selectedDebt.paid)+' hasta '+money(selectedDebt.effective)+'. El descuento se calculará automáticamente.');updatePreview()});
$('#discount-calc').on('change',function(){if(!selectedDebt)return;const v=this.value,input=$('#discount-value').val('');if(v==='Porcentaje'){input.attr({min:0,max:100,placeholder:'Ej.: 20'});$('#discount-value-label').text('Porcentaje de descuento (%)');$('#discount-value-help').text('Indique qué porcentaje desea descontar del monto exigible actual.')}else if(v==='Monto descontado'){input.attr({min:0,max:Number(selectedDebt.available||0).toFixed(2),placeholder:'Ej.: 50.00'});$('#discount-value-label').text('¿Cuánto desea descontar? (S/)');$('#discount-value-help').text('Escriba el importe que se restará de la deuda actual.')}else{input.attr({min:Number(selectedDebt.paid||0).toFixed(2),max:Number(selectedDebt.effective||0).toFixed(2),placeholder:'Ej.: '+Number(selectedDebt.effective||0).toFixed(2)});$('#discount-value-label').text('¿Cuál será el monto final a pagar? (S/)');$('#discount-value-help').text('Escriba el nuevo total de la deuda. El descuento se calculará automáticamente.')}updatePreview();input.focus()});
$('#discount-value').on('input',updatePreview);
$('#discount-form').on('submit',function(e){e.preventDefault();start_load();$('#discount-message').empty();let action=editId?(editSource==='payment'?'update_payment_discount':'update'):'save';$.ajax({url:api+'?action='+action,method:'POST',data:$(this).serialize(),dataType:'json'}).done(r=>{if(r.status){alert_toast(r.message,'success');modal.modal('hide');if(window.reload_discounts)window.reload_discounts()}else error(r.message)}).fail(x=>error((x.responseJSON||{}).message||'No se pudo guardar el beneficio.')).always(end_load)})})(jQuery);
</script>
